const jwt = global.get('jwt');

const authHeader = (msg.req && msg.req.headers && msg.req.headers['authorization']) || '';
const genericError = 'การยืนยันตัวตนล้มเหลว กรุณาเข้าสู่ระบบใหม่';

if (!authHeader || !authHeader.startsWith('Bearer ')) {
    node.warn('JWT Verify Failed: Missing or invalid Authorization header format');
    msg.statusCode = 401;
    msg.payload = { error: genericError };
    return [null, msg];
}

const token = authHeader.substring(7).trim();
const secret = env.get('JWT_SECRET');

try {
    const decoded = jwt.verify(token, secret, {
        algorithms: ['HS256']
    });

    const subNum = Number(decoded.sub);
    if (!Number.isInteger(subNum) || subNum <= 0) {
        node.warn('JWT Verify Failed: Subject is not a valid positive integer: ' + decoded.sub);
        msg.statusCode = 401;
        msg.payload = { error: genericError };
        return [null, msg];
    }

    msg.userId = subNum;
    return [msg, null];
} catch (err) {
    node.warn('JWT Verify Error: ' + (err.message || err));
    msg.statusCode = 401;
    msg.payload = { error: genericError };
    return [null, msg];
}

const mysql = global.get('mysql');
let conn;
try {
  conn = await mysql.createConnection({
    host: env.get('MYSQL_HOST'),
    user: env.get('MYSQL_USER'),
    password: env.get('MYSQL_PASSWORD'),
    database: env.get('MYSQL_DATABASE')
  });
  const [rows] = await conn.execute('SELECT 1 as status, "connected" as message');
  msg.statusCode = 200;
  msg.payload = rows;
} catch (err) {
  node.error(err);
  msg.statusCode = 500;
  msg.payload = { error: 'internal_error' };
} finally {
  if (conn) await conn.end();
}
return msg;

const mysql = global.get('mysql');
const bcrypt = global.get('bcrypt');

const body = msg.payload || {};
const name = typeof body.name === 'string' ? body.name.trim() : '';
const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : '';
const password = typeof body.password === 'string' ? body.password : '';

// 1. Validation
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!name) {
    msg.statusCode = 400;
    msg.payload = { error: 'กรุณากรอกชื่อ-นามสกุล' };
    return msg;
}
if (name.length > 100) {
    msg.statusCode = 400;
    msg.payload = { error: 'ชื่อ-นามสกุลต้องมีความยาวไม่เกิน 100 ตัวอักษร' };
    return msg;
}
if (!email || !emailRegex.test(email)) {
    msg.statusCode = 400;
    msg.payload = { error: 'รูปแบบอีเมลไม่ถูกต้อง' };
    return msg;
}
if (email.length > 191) {
    msg.statusCode = 400;
    msg.payload = { error: 'อีเมลต้องมีความยาวไม่เกิน 191 ตัวอักษร' };
    return msg;
}

const passwordBytes = Buffer.byteLength(password, 'utf8');
if (passwordBytes < 8) {
    msg.statusCode = 400;
    msg.payload = { error: 'รหัสผ่านต้องมีความยาวอย่างน้อย 8 ตัวอักษร' };
    return msg;
}
if (passwordBytes > 72) {
    msg.statusCode = 400;
    msg.payload = { error: 'รหัสผ่านต้องมีขนาดไม่เกิน 72 ไบต์' };
    return msg;
}

let conn;
try {
    conn = await mysql.createConnection({
        host: env.get('MYSQL_HOST'),
        user: env.get('MYSQL_USER'),
        password: env.get('MYSQL_PASSWORD'),
        database: env.get('MYSQL_DATABASE')
    });

    // 2. Hash Password (cost 10)
    const passwordHash = await bcrypt.hash(password, 10);

    // 3. Parameterized Query Insert User
    const [result] = await conn.execute(
        'INSERT INTO users (name, email, password_hash) VALUES (?, ?, ?)',
        [name, email, passwordHash]
    );

    msg.statusCode = 201;
    msg.payload = {
        message: 'สมัครสมาชิกสำเร็จ',
        user: {
            id: result.insertId,
            name: name,
            email: email
        }
    };
} catch (err) {
    // Check duplicate email constraint (MySQL ER_DUP_ENTRY = 1062)
    if (err.errno === 1062 || err.code === 'ER_DUP_ENTRY') {
        msg.statusCode = 409;
        msg.payload = { error: 'อีเมลนี้ถูกใช้งานแล้วในระบบ' };
    } else {
        node.error('Register error: ' + (err.message || err));
        msg.statusCode = 500;
        msg.payload = { error: 'เกิดข้อผิดพลาดภายในระบบ ไม่สามารถดำเนินการได้' };
    }
} finally {
    if (conn) await conn.end();
}

return msg;

const mysql = global.get('mysql');
const bcrypt = global.get('bcrypt');
const jwt = global.get('jwt');

const body = msg.payload || {};
const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : '';
const password = typeof body.password === 'string' ? body.password : '';

// 1. Validation
if (!email || !password) {
    msg.statusCode = 400;
    msg.payload = { error: 'กรุณากรอกอีเมลและรหัสผ่าน' };
    return msg;
}

const genericAuthError = 'อีเมลหรือรหัสผ่านไม่ถูกต้อง';
// Valid bcrypt cost 10 dummy hash for timing attack mitigation
const dummyHash = '$2b$10$9UOST935FBlnR3pYKmNh4e86NrXqRYginu7/1LIBruOwR0jDux4zy';

let conn;
try {
    conn = await mysql.createConnection({
        host: env.get('MYSQL_HOST'),
        user: env.get('MYSQL_USER'),
        password: env.get('MYSQL_PASSWORD'),
        database: env.get('MYSQL_DATABASE')
    });

    // 2. Query user by email (Parameterized Query)
    const [rows] = await conn.execute(
        'SELECT id, name, email, password_hash, notify_enabled FROM users WHERE email = ? LIMIT 1',
        [email]
    );

    if (rows.length === 0) {
        // Constant-time compare against dummy hash
        await bcrypt.compare(password, dummyHash);
        msg.statusCode = 401;
        msg.payload = { error: genericAuthError };
        return msg;
    }

    const user = rows[0];

    // 3. Verify password with bcrypt
    const isPasswordValid = await bcrypt.compare(password, user.password_hash);
    if (!isPasswordValid) {
        msg.statusCode = 401;
        msg.payload = { error: genericAuthError };
        return msg;
    }

    // 4. Generate JWT Token with sub as String(user.id) only
    const secret = env.get('JWT_SECRET');
    const expiresIn = env.get('JWT_EXPIRES_IN') || '2h';
    const payload = {
        sub: String(user.id)
    };

    const token = jwt.sign(payload, secret, { expiresIn: expiresIn });

    msg.statusCode = 200;
    msg.payload = {
        message: 'เข้าสู่ระบบสำเร็จ',
        token: token,
        user: {
            id: user.id,
            name: user.name,
            email: user.email,
            notify_enabled: Boolean(user.notify_enabled)
        }
    };
} catch (err) {
    node.error('Login error: ' + (err.message || err));
    msg.statusCode = 500;
    msg.payload = { error: 'เกิดข้อผิดพลาดภายในระบบ ไม่สามารถดำเนินการได้' };
} finally {
    if (conn) await conn.end();
}

return msg;

const mysql = global.get('mysql');

let conn;
try {
    conn = await mysql.createConnection({
        host: env.get('MYSQL_HOST'),
        user: env.get('MYSQL_USER'),
        password: env.get('MYSQL_PASSWORD'),
        database: env.get('MYSQL_DATABASE')
    });

    // SELECT only non-sensitive columns, NO password_hash
    const [rows] = await conn.execute(
        'SELECT id, name, email, notify_enabled, created_at FROM users WHERE id = ? LIMIT 1',
        [msg.userId]
    );

    if (rows.length === 0) {
        node.warn('User not found in DB for valid token userId: ' + msg.userId);
        msg.statusCode = 401;
        msg.payload = { error: 'การยืนยันตัวตนล้มเหลว กรุณาเข้าสู่ระบบใหม่' };
        return msg;
    }

    const user = rows[0];
    msg.statusCode = 200;
    msg.payload = {
        id: user.id,
        name: user.name,
        email: user.email,
        notify_enabled: Boolean(user.notify_enabled),
        created_at: user.created_at
    };
} catch (err) {
    node.error('Get profile error: ' + (err.message || err));
    msg.statusCode = 500;
    msg.payload = { error: 'เกิดข้อผิดพลาดภายในระบบ ไม่สามารถดำเนินการได้' };
} finally {
    if (conn) await conn.end();
}

return msg;
